      score += djsTopicAuthorityScore(entry, info);
      score += djsSeoFreshnessScore(entry);

      if (family && sameBrand && !sameFamily) score -= 7;
      if (family && sameBrand && !info.family) score -= 4;
      if (family && !sameFamily && info.family) score -= 3;

